def rk4_step(u):
    def rhs(uu):
        return -vx_field * grad_x(uu) - vy_field * grad_y(uu) + alpha * laplacian(uu) + R

    k1 = rhs(u)
    k2 = rhs(u + 0.5 * ode_dt * k1)
